-- 484: Original BrillaPrep Cambridge A-Level Biology (9700) Immunity questions (batch alevel-bio-sprint2-001).
-- Curriculum-aligned practice content; not official Cambridge International or WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_484_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_484_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_immunity_s2_001', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A breastfed baby receives antibodies against intestinal infections in its mother’s milk. Which type of immunity does this give the baby?', 'multiple_choice', NULL, '["A. Artificial passive immunity","B. Natural active immunity","C. Artificial active immunity","D. Natural passive immunity"]', 'D', 'The baby receives ready-made antibodies rather than making its own, so the immunity is passive; it happens naturally through breast milk (or across the placenta), not by medical injection, so it is natural. Artificial passive immunity is an injection of antibodies such as antivenom; active immunity — natural or artificial — means the person’s own lymphocytes respond to antigen and produce antibodies and memory cells, which gives longer-lasting protection. Therefore the correct answer is D: Natural passive immunity.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_immunity_s2_002', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'A helper T cell recognises antigen presented on the surface of a macrophage. Which events then follow?', 'multiple_choice', NULL, '["A. The helper T cell clones itself and secretes cytokines that stimulate B cells to become plasma cells and that activate cytotoxic T cells and macrophages","B. The helper T cell immediately secretes large quantities of antibody","C. The helper T cell engulfs the macrophage by phagocytosis","D. The helper T cell converts directly into a plasma cell"]', 'A', 'Helper T cells are the coordinators of the specific immune response: once activated by an antigen-presenting cell they proliferate and release cytokines that drive B-cell clonal selection and differentiation into antibody-secreting plasma cells, stimulate cytotoxic (killer) T cells, and enhance macrophage activity. Only plasma cells derived from B cells secrete antibody — the commonest confusion at this level; T cells are not phagocytes and cannot become plasma cells. Therefore the correct answer is A: The helper T cell clones itself and secretes cytokines that stimulate B cells to become plasma cells and that activate cytotoxic T cells and macrophages.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Describe', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_immunity_s2_003', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Why is the secondary immune response to a previously encountered pathogen faster, and why does it produce a higher antibody concentration, than the primary response?', 'multiple_choice', NULL, '["A. High levels of antibody from the first infection remain in the blood for life","B. Memory B cells and memory T cells made during the first exposure proliferate rapidly on re-exposure, producing many plasma cells at once","C. The pathogen is weaker the second time it infects the body","D. Antibodies from the first infection mutate to match the pathogen better"]', 'B', 'The primary response leaves long-lived memory cells; on re-infection these are already specific for the pathogen, so clonal expansion begins immediately, the antibody concentration rises steeply within hours rather than days, and it peaks far higher. Antibody from the first infection actually falls to low levels within months — that is the misconception this question targets; the pathogen is not weaker, and existing antibodies do not mutate — the new antibody comes from newly generated plasma cells. Therefore the correct answer is B: Memory B cells and memory T cells made during the first exposure proliferate rapidly on re-exposure, producing many plasma cells at once.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_immunity_s2_004', 'topic_alevel_bio_immunity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'HIV destroys helper T cells, eventually causing AIDS. Why does the loss of helper T cells make patients vulnerable to opportunistic infections?', 'multiple_choice', NULL, '["A. HIV directly attacks and kills every type of body cell, including skin and nerve cells","B. HIV destroys the bone marrow, so no blood cells of any kind are produced","C. Helper T cells coordinate both the humoral and the cell-mediated responses, so without them B cells cannot be properly activated and cytotoxic T cells cannot be stimulated, crippling defence against many pathogens","D. The patient’s antibodies attack their own tissues once helper T cells are gone"]', 'C', 'Helper T cells sit at the hub of specific immunity: their cytokines are required for full B-cell activation and antibody production, for activating the cytotoxic T cells that kill virus-infected cells, and for boosting macrophage activity. As HIV depletes them, the whole network fails, so normally harmless organisms cause severe opportunistic infections. HIV does not kill skin or nerve cells directly, does not destroy the bone marrow, and AIDS is immune collapse, not autoimmunity. Therefore the correct answer is C: Helper T cells coordinate both the humoral and the cell-mediated responses, so without them B cells cannot be properly activated and cytotoxic T cells cannot be stimulated, crippling defence against many pathogens.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_484_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_484_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_484_guard;
INSERT INTO _migration_484_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_484_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_484_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_484_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_484_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_484_guard;
INSERT INTO _migration_484_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_484_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 4 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_484_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 4 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_484_expected e ON e.id = q.id) = 4 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_484_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
DROP TABLE _migration_484_guard;
